import { type AudioPlayer, createAudioPlayer, setAudioModeAsync } from 'expo-audio';
import { Platform } from 'react-native';

/** VYNR's original UI sounds (generated by scripts/generate-sounds.py). */
const SOURCES = {
  shutter: require('../../assets/sounds/shutter.wav'),
  identified: require('../../assets/sounds/identified.wav'),
  discovery: require('../../assets/sounds/discovery.wav'),
  discoveryRare: require('../../assets/sounds/discovery-rare.wav'),
} as const;

export type SoundName = keyof typeof SOURCES;

const players = new Map<SoundName, AudioPlayer>();
let configured = false;

/**
 * Plays a short UI sound. Never throws and never blocks: a missing audio
 * session or a failed load just means silence. Mixes with the player's music
 * and stays silent when the iOS ring/silent switch is set to silent.
 */
export function playSound(name: SoundName, enabled: boolean): void {
  if (!enabled || Platform.OS === 'web') return;
  try {
    if (!configured) {
      configured = true;
      void setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(() => undefined);
    }
    let p = players.get(name);
    if (!p) {
      p = createAudioPlayer(SOURCES[name]);
      players.set(name, p);
    }
    void p.seekTo(0).then(() => p.play()).catch(() => undefined);
  } catch {
    // Sound is decoration only.
  }
}
